  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Human PET imaging showed sembragiline crosses the BBB and inhibits brain MAO-B, providing direct evidence of meaningful CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In mice, Org-25543 had a free brain/plasma ratio of approximately 0.5 and readily crossed the BBB, supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Whole-body autoradiography in rats showed lapatinib brain/plasma ratios below 0.13 with only low CNS radioactivity, indicating inadequate normal-barrier CNS access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Most direct in-vivo evidence from similar molecules supports meaningful CNS access, including human PET and rodent brain/plasma measurements, while the main negative evidence comes from lapatinib's poor normal-barrier brain penetration. Overall prediction is pass, but confidence is low because Morgan similarities are modest and the evidence is mixed.",
  "evidence_gaps": [
    "Morgan similarities are low (0.23–0.27), limiting transferability to the query.",
    "Lapatinib evidence is mixed, with positive disrupted-BBB records but negative normal-barrier brain/plasma ratios.",
    "No direct query-specific CNS exposure data were provided."
  ],
